struct event;
struct element;

template <class T> struct list_node {
    list_node *next;
    list_node *prev;
    T data;
};

template <class T> struct list_iterator {
    list_node<T> *node;
    T &operator*() const { return node->data; }
    list_iterator &operator++() { node = node->next; return *this; }
    bool operator!=(const list_iterator &other) const { return node != other.node; }
};

template <class T> struct list_layout {
    list_node<T> *sentinel;
    list_iterator<T> begin() { list_iterator<T> it = { sentinel->next }; return it; }
    list_iterator<T> end() { list_iterator<T> it = { sentinel }; return it; }
};

struct event {
    int type;
    element *owner;
    float wait_time;
    float duration;
    float elapsed;
    virtual void do_event(const float &) = 0;
};

struct element {
    void *vtable;
    element *parent;
    int type;
    list_layout<element *> subelements;
    char pad[0x84];
    list_layout<event *> event_run_list;
    void event_flush();
};

extern "C" list_iterator<event *> erase_events(
    list_layout<event *> *, list_iterator<event *>, list_iterator<event *>)
    __asm__("erase__t4list2ZP5eventZt12my_allocator1ZP5eventGt14_List_iterator3ZP5eventZRP5eventZPP5eventT1");
extern "C" void builtin_delete(void *) __asm__("__builtin_delete");

void element::event_flush()
{
    list_iterator<event *> it;
    list_iterator<element *> iu;

    for (it = event_run_list.begin(); it != event_run_list.end(); ++it)
    {
        (*it)->do_event(1.0f);
        builtin_delete(*it);
    }
    erase_events(&event_run_list, event_run_list.begin(), event_run_list.end());

    for (iu = subelements.begin(); iu != subelements.end(); ++iu)
    {
        (*iu)->event_flush();
    }
}
